import 'package:graphql_gen/graphql_gen.dart';

/// Builds a query by hand. In a real project the field names come from the
/// enums generated by `graphql_gen_generator`, e.g. `BookFields.values`.
void main() {
  final query = GraphQLQueryBuilder(name: 'Books')
      .withOperation(
        operationName: 'books',
        arguments: GraphQLArgumentBuilder()
            .withArgument('first', 10)
            .withArgument('genre', const GraphQLEnumValue('FICTION')),
        fields: GraphQLFieldBuilder()
            .withFields(['id', 'title'])
            .withField(
              'author',
              nestedField: GraphQLFieldBuilder().withFields(['id', 'name']),
            ),
      )
      .build();

  print(query);
}
